import { BufferGeometry, BufferAttribute, Mesh, MeshBasicMaterial, Scene, VSMShadowMap, type Material, type PointLight, type WebGLRenderer } from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

// Only MergedStaticGroup's immutable sibling geometry is registered here.
const registrations = new WeakMap<Scene, Set<Batch>>();
/** Diagnostic override; does not change the normal image or scene settings. */
export const staticShadowBatching = { enabled: true };

type Source = { mesh: Mesh; geometry: BufferGeometry; material: Material };
type Batch = { sources: Source[]; geometry: BufferGeometry; material: MeshBasicMaterial };

function eligible(mesh: Mesh): mesh is Mesh<BufferGeometry, Material> {
  if (mesh.type !== 'Mesh' || !mesh.castShadow || Array.isArray(mesh.material) ||
      mesh.customDepthMaterial || mesh.customDistanceMaterial || Object.keys(mesh.geometry.morphAttributes).length) return false;
  const material = mesh.material as Material & { displacementMap?: unknown; wireframe?: boolean };
  return !material.transparent && !material.alphaTest && !material.alphaToCoverage &&
    !material.clippingPlanes?.length && !material.displacementMap && !material.wireframe;
}

/** Sources are the static, same-transform siblings already merged by beauty material. */
export function registerStaticShadowBatches(scene: Scene, meshes: Mesh[]): () => void {
  const groups = new Map<string, Source[]>();
  for (const mesh of meshes) {
    if (!eligible(mesh)) continue;
    mesh.updateMatrix();
    const material = mesh.material;
    const key = JSON.stringify([mesh.layers.mask, material.side, material.shadowSide, !!mesh.geometry.index, mesh.frustumCulled, mesh.matrix.elements]);
    const sources = groups.get(key) ?? [];
    sources.push({ mesh, geometry: mesh.geometry, material });
    groups.set(key, sources);
  }
  let registered = registrations.get(scene);
  if (!registered) { registered = new Set(); registrations.set(scene, registered); }
  const batches: Batch[] = [];
  for (const sources of groups.values()) {
    if (sources.length < 2) continue;
    const geometries = sources.map(({ geometry }) => {
      const position = geometry.getAttribute('position');
      const copy = new BufferGeometry();
      // Depth needs only positions here: no alpha masks, displacement or skinning.
      const positions = new Float32Array(position.count * 3);
      for (let i = 0; i < position.count; i++) {
        positions[i * 3] = position.getX(i); positions[i * 3 + 1] = position.getY(i); positions[i * 3 + 2] = position.getZ(i);
      }
      copy.setAttribute('position', new BufferAttribute(positions, 3));
      if (geometry.index) copy.setIndex(geometry.index.clone());
      copy.setDrawRange(geometry.drawRange.start, geometry.drawRange.count);
      return copy;
    });
    // These geometries were generated by MergedStaticGroup with full draw ranges.
    if (geometries.some(g => g.drawRange.start !== 0 || g.drawRange.count !== Infinity)) {
      geometries.forEach(g => g.dispose());
      throw new Error('Static shadow batching requires complete static geometries');
    }
    const geometry = mergeGeometries(geometries, false);
    geometries.forEach(g => g.dispose());
    if (!geometry) throw new Error('Incompatible static shadow geometries');
    geometry.computeBoundingSphere();
    const first = sources[0].material;
    const material = new MeshBasicMaterial({ side: first.side });
    material.shadowSide = first.shadowSide;
    const batch = { sources, geometry, material };
    batches.push(batch); registered.add(batch);
  }
  return () => {
    for (const batch of batches) {
      registered.delete(batch); batch.geometry.dispose(); batch.material.dispose();
    }
  };
}

/** Main render lists already hold their original geometries/materials at this point. */
export function installStaticShadowBatching(renderer: WebGLRenderer, scene: Scene): () => void {
  const original = renderer.shadowMap.render;
  renderer.shadowMap.render = function (lights, currentScene, camera) {
    if (!staticShadowBatching.enabled || currentScene !== scene || renderer.shadowMap.type === VSMShadowMap ||
        lights.some(light => {
          const point = light as PointLight;
          return point.isPointLight && (point.shadow.autoUpdate || point.shadow.needsUpdate);
        }) ||
        !renderer.shadowMap.enabled || (!renderer.shadowMap.autoUpdate && !renderer.shadowMap.needsUpdate)) {
      return original.call(this, lights, currentScene, camera);
    }
    const applied: Batch[] = [];
    try {
      for (const batch of registrations.get(scene) ?? []) {
        const { sources, geometry, material } = batch;
        const first = sources[0].mesh;
        // If a formerly static item changes, render the originals normally.
        // This also preserves independent visibility, layers and shadow toggles.
        if (sources.some(source => !eligible(source.mesh) || !source.mesh.visible || !source.material.visible ||
            source.mesh.parent !== first.parent || source.mesh.geometry !== source.geometry ||
            source.mesh.material !== source.material || source.mesh.layers.mask !== first.layers.mask || source.mesh.frustumCulled !== first.frustumCulled ||
            !source.mesh.matrix.equals(first.matrix) || source.material.side !== material.side ||
            source.material.shadowSide !== material.shadowSide)) continue;
        applied.push(batch);
        first.geometry = geometry; first.material = material;
        for (let i = 1; i < sources.length; i++) sources[i].mesh.castShadow = false;
      }
      return original.call(this, lights, currentScene, camera);
    } finally {
      for (let b = applied.length - 1; b >= 0; b--) {
        const { sources } = applied[b];
        sources[0].mesh.geometry = sources[0].geometry; sources[0].mesh.material = sources[0].material;
        for (let i = 1; i < sources.length; i++) sources[i].mesh.castShadow = true;
      }
    }
  };
  return () => { renderer.shadowMap.render = original; };
}
